			eventManager.completeJdbcPreparedStatementExecutionEvent( jdbcPreparedStatementExecutionEvent, sql );
			jdbcExecuteStatementEnd();
			sqlStatementLogger.logSlowQuery( sql, executeStartNanos, context() );
