for(Map.Entry<String,PreparedStatement> entry: getStatements().entrySet()){final String statementSQL=entry.getKey();
tryfinal PreparedStatement statement=entry.getValue();
final int rowCount=jdbcCoordinator.getResultSetReturn().executeUpdate(statement);
getKey().getExpectation().verifyOutcome(rowCount,statement,0,statementSQL);
jdbcCoordinator.getLogicalConnection().getResourceRegistry().release(statement);
jdbcCoordinator.afterStatementExecution();
catch(SQLException e)abortBatch(e);
throw sqlExceptionHelper().convert(e,"could not execute non-batched batch statement",statementSQL);
catch(RuntimeException e)abortBatch(e);
throw e;
}getStatements().clear();
}

