methodSignature: org.hibernate.engine.jdbc.batch.internal.BatchingBatch#addToBatch
 methodBody: public void addToBatch() {
trycurrentStatement.addBatch();
catch(SQLException e)abortBatch(e);
LOG.debug("SQLException escaped proxy",e);
throw sqlExceptionHelper().convert(e,"could not perform addBatch",currentStatementSql);
catch(RuntimeException e)abortBatch(e);
throw e;
statementPosition++;
if(statementPosition >= getKey().getBatchedStatementCount()){batchPosition++;
if(batchPosition == batchSize){notifyObserversImplicitExecution();
performExecution();
batchPosition=0;
batchExecuted=true;
}statementPosition=0;
}}

