			field.setAccessible( true );
			return (DatabaseVersion) field.get( null );
		}
		catch (IllegalAccessException | NoSuchFieldException e) {
			throw new RuntimeException( "Error extracting '" + versionConstantName + "' from '" + dialectClass + "'", e );
		}
