				sqle -> {
					switch ( extractErrorCode( sqle ) ) {
						case 2627:
						case 2601:
							String message = sqle.getMessage();
							if ( message.contains("unique index ") ) {
								return extractUsingTemplate( "unique index '", "'", message);
							}
							else {
