/**
 * A dialect for Microsoft SQL Server 2008 and above
 *
 * @author Gavin King
 */
public class SQLServerDialect extends AbstractTransactSQLDialect {
	private final static DatabaseVersion MINIMUM_VERSION = DatabaseVersion.make( 11, 0 );

