	@Override
	public <R, U, RL> CompletionStage<R> fireEventOnEachListener(
			final U event,
			final Function<RL, Function<U, CompletionStage<R>>> fun) {
		CompletionStage<R> ret = COMPLETED;
		final T[] ls = listeners;
		if ( ls != null && ls.length != 0 ) {
			for ( T listener : ls ) {
