		final T[] ls = listeners;
		if ( ls != null && ls.length != 0 ) {
			for ( T listener : ls ) {
				//to preserve atomicity of the Session methods
				//call apply() from within the arg of thenCompose()
				ret = ret.thenCompose( v -> fun.apply( (RL) listener ).apply( event ) );
