							|| lcToken.equals( "time" ) && "with".equals( nextToken )
							|| lcToken.equals( "timestamp" ) && "with".equals( nextToken )
							|| lcToken.equals( "time" ) && "zone".equals( nextToken );
					}
					else {
						return false;
					}
				}
				else {
					return false;
				}
