							columnNames.get( selectionIndex ),
							tableGroup.resolveTableReference(
									fetchPath,
									keyDescriptor.getKeyPart(),
									selectableMapping.getContainingTableExpression()
							),
							selectableMapping,
							jdbcResultsMetadata,
							domainResultCreationState
					); }
