			final String generatedProp = entity.getGeneratedProp();
			assertThat( generatedProp ).startsWith( "generated" );
			assertThat( Integer.parseInt( generatedProp.split( "_" )[1] ) ).isGreaterThan( generatedCount );
		} );
	}

