			getStaticFetchableList().forEach( fetchableConsumer );
//			staticFetchableList.forEach( fetchableConsumer );
		}
		else {
			if ( treatTargetType.isTypeOrSuperType( this ) ) {
				visitSubTypeAttributeMappings( fetchableConsumer );
