			return;
		}

		// reset the identifier
		final Object defaultIdentifier = identifierMapping.getUnsavedStrategy().getDefaultValue( currentId );
		setIdentifier( entity, defaultIdentifier, session );

		// reset the version
		if ( versionMapping != null ) {
